def _carries_all_canonical(note, tags):
    """True if the note carries every tag in ``tags``, matched canonically.

    This is list --tag --normalize-tags' matching rule (the old
    normalization era's, restored strictly opt-in): every query tag and
    every stored tag pass through _normalize_tag, and each canonical query
    tag must equal one of the note's canonical stored tags. So a note
    tagged "API Design" or "api-design" is a hit for the query tag "api
    design", "API   Design" or "API Design", and records written before
    tags existed have no "tags" key, carry no tags, and only match an
    empty filter -- exactly as with exact matching.
    """
    canonical = {_normalize_tag(t) for t in note.get("tags", [])}
    return all(_normalize_tag(tag) in canonical for tag in tags)", "old_string": "    note_tags = note.get("tags", [])
